using System;
using System.IO;
using System.Diagnostics;
using System.Windows.Forms;
using System.Drawing;
using System.Collections.Generic;
using System.Web.Script.Serialization;
class Launcher {
 static string Root=AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar);
 static JavaScriptSerializer Json=new JavaScriptSerializer();
 static string Q(string s){return "\""+s.Replace("\"","\\\"")+"\"";}
 static Dictionary<string,object> Config(){return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Root,"current.json")));}
 static string Run(string action){var c=Config();string v=Convert.ToString(c["version"]);if(v.IndexOfAny(new[]{'/', '\\'})>=0||v.Contains(".."))throw new Exception("Invalid installed version");string dir=Path.Combine(Root,"versions",v);var p=new Process();p.StartInfo=new ProcessStartInfo(Path.Combine(dir,"runtime","node.exe"),Q(Path.Combine(dir,"suite-control.cjs"))+" "+action+" "+Q(Root));p.StartInfo.UseShellExecute=false;p.StartInfo.CreateNoWindow=true;p.StartInfo.WindowStyle=ProcessWindowStyle.Hidden;p.StartInfo.RedirectStandardOutput=true;p.StartInfo.RedirectStandardError=true;p.StartInfo.StandardOutputEncoding=System.Text.Encoding.UTF8;p.StartInfo.StandardErrorEncoding=System.Text.Encoding.UTF8;p.Start();string stdout=p.StandardOutput.ReadToEnd(),stderr=p.StandardError.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception(stderr.Trim());return stdout.Trim();}
 static void Open(){var r=Json.Deserialize<Dictionary<string,object>>(Run("start"));string url=Convert.ToString(r["url"]);if(!url.StartsWith("http://127.0.0.1:"))throw new Exception("Invalid local address");Process.Start(url);}
 static void Login(){var c=Config();string exe=Path.Combine(Root,"versions",Convert.ToString(c["version"]),"components","codex","bin","codex.exe");var si=new ProcessStartInfo(exe,"login");si.UseShellExecute=false;si.WorkingDirectory=Root;si.EnvironmentVariables["CODEX_HOME"]=Path.Combine(Root,"data","adapter","codex");si.EnvironmentVariables.Remove("OPENAI_API_KEY");si.EnvironmentVariables.Remove("CODEX_API_KEY");Process.Start(si);}
 [STAThread] static int Main(string[] args){Application.EnableVisualStyles();try{if(args.Length>0&&args[0]=="--background"){Run("start");return 0;}if(args.Length==0||args[0]=="--open"){Open();return 0;}if(args[0]=="--stop"){Run("stop");return 0;}if(args[0]=="--login"){Login();return 0;}var f=new Form{Text="PACTIQO · управление комплектом",Width=650,Height=430,StartPosition=FormStartPosition.CenterScreen,Font=new Font("Segoe UI",10)};var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(22),WrapContents=false,AutoScroll=true};var title=new Label{Text="PACTIQO MODUS / Desk + Адаптер + Codex",Width=580,Height=42,Font=new Font("Segoe UI",15,FontStyle.Bold)};var status=new Label{Text="Программы и данные находятся в отдельном клиентском профиле.",Width=580,Height=85};panel.Controls.Add(title);panel.Controls.Add(status);Action<string,Action> add=(name,action)=>{var b=new Button{Text=name,Width=570,Height=34};b.Click+=(s,e)=>{try{action();}catch(Exception ex){status.Text=ex.Message;}};panel.Controls.Add(b);};add("Открыть платформу",()=>Open());add("Войти в Codex под учётной записью клиента",()=>Login());add("Показать локальные учётные записи",()=>Process.Start("notepad.exe",Q(Path.Combine(Root,"data","platform","ACCESS.txt"))));add("Проверить компоненты",()=>{var r=Json.Deserialize<Dictionary<string,object>>(Run("status"));status.Text="Комплект работает. "+Convert.ToString(r["url"])+"\nВход Codex проверяется в разделе Адаптер платформы.";});add("Остановить фоновые компоненты",()=>{Run("stop");status.Text="Компоненты остановлены. Данные сохранены.";});f.Controls.Add(panel);Application.Run(f);return 0;}catch(Exception e){MessageBox.Show(e.Message,"PACTIQO",MessageBoxButtons.OK,MessageBoxIcon.Warning);return 1;}}
}
